// ========================================

// ---------- CONFIGURATION ----------

const TARGET_NAF = new Set([
    // Nettoyage
    "81.21Z","81.22Z","81.29A","81.29B",

    // BTP
    "41.20A","41.20B",
    "43.11Z","43.12A","43.12B",
    "43.21A","43.22A","43.29A",
    "43.31Z","43.32A","43.32B",
    "43.34Z","43.39Z",
    "43.91A","43.99C","43.99D",

    // Transport
    "49.41A","49.41B","49.41C",
    "52.10A","52.10B",
    "52.24A","52.24B",
    "52.29A","52.29B",

    // Services
    "88.10A","88.10B",

    // Santé
    "86.10Z","86.21Z","86.22A",
    "87.10A","87.30A","88.99B",

    // Comptabilité
    "69.20Z",

    // Immobilier
    "68.31Z","68.32A","68.32B"
]);

const VALID_SIZES = new Set([
    "10 à 19 salariés",
    "20 à 49 salariés",
    "50 à 99 salariés",
    "100 à 199 salariés",
    "200 à 249 salariés"
]);

const STAFFING_KEYWORDS = [
    "adecco",
    "randstad",
    "manpower",
    "proman",
    "synergie",
    "crit",
    "actual",
    "supplay",
    "temporis",
    "hays",
    "page personnel",
    "michael page"
];

// ---------- HELPERS ----------

function normalize(name){

    if(!name) return "";

    return name
        .toLowerCase()
        .replace(/\b(sas|sasu|sarl|sa|eurl|scop|association|asso)\b/g,"")
        .replace(/[^\p{L}\p{N}]/gu,"")
        .trim();

}

function isStaffing(name){

    const n = normalize(name);

    return STAFFING_KEYWORDS.some(k=>n.includes(k));

}

// ---------- READ RESPONSE ----------

