for(const item of items){

    if(Array.isArray(item.json.resultats))
        offers.push(...item.json.resultats);

}

const seenCompanies = new Set();

const qualified=[];

const stats={
    total:offers.length,
    rejected:{
        naf:0,
        size:0,
        staffing:0,
        duplicate:0,
        missingCompany:0
    }
};

// ---------- MAIN LOOP ----------

for(const offer of offers){

    const company = offer.entreprise?.nom;

    if(!company){

        stats.rejected.missingCompany++;
        continue;

    }

    const naf = offer.codeNAF;

    if(!TARGET_NAF.has(naf)){

        stats.rejected.naf++;
        continue;

    }

    const size = offer.trancheEffectifEtab;

    if(size && !VALID_SIZES.has(size)){

        stats.rejected.size++;
        continue;

    }

    if(isStaffing(company)){

        stats.rejected.staffing++;
        continue;

    }

    const companyKey = normalize(company);

    if(seenCompanies.has(companyKey)){

        stats.rejected.duplicate++;
        continue;

    }

    seenCompanies.add(companyKey);

