        ville:
            offer.lieuTravail?.libelle || "",

        codePostal:
            offer.lieuTravail?.codePostal || "",

        // ==========================
        // France Travail data
        // (kept for scoring)
        // ==========================

        intitule:
            offer.intitule || "",

        dateCreation:
            offer.dateCreation || "",

        offresManqueCandidats:
            offer.offresManqueCandidats || false,

        nombrePostes:
            offer.nombrePostes || 1,

        qualificationCode:
