});

}

// ---------- OUTPUT ----------

console.log({

    total:stats.total,

    accepted:qualified.length,

    rejected:stats.rejected

});



return qualified;

// ========================================
// NODE 5 - Prospect Intelligence
// ========================================

return items.map(item => {

    const p = item.json;

    let score = 0;

    const trace = [...(p.qualification_trace || [])];

    // -----------------------------
    // Candidate shortage
    // -----------------------------

    if (p.offresManqueCandidats) {

        score += 30;

        trace.push("candidate_shortage");

    }

    // -----------------------------
    // Recent publication
    // -----------------------------

    if (p.dateCreation) {

        const days =

            (Date.now() - new Date(p.dateCreation).getTime())

            / 86400000;

        if (days <= 7) {

            score += 25;

            trace.push("posted_last_7_days");

        }

        else if (days <= 14) {

            score += 18;

            trace.push("posted_last_14_days");

        }

        else if (days <= 30) {

            score += 10;

            trace.push("posted_last_30_days");

        }

    }

    // -----------------------------
    // Multiple positions
    // -----------------------------

    if (p.nombrePostes >= 5) {

        score += 25;

        trace.push("5+_positions");

    }

    else if (p.nombrePostes >= 3) {

        score += 18;

        trace.push("3+_positions");

    }

    else if (p.nombrePostes >= 2) {

        score += 10;

        trace.push("2_positions");

    }

    // -----------------------------
    // Beginner accepted
    // -----------------------------

    if (p.experienceExige === "D") {

        score += 10;

        trace.push("accepts_beginners");

    }

    // -----------------------------
    // Part time
    // -----------------------------

    if (

        p.dureeTravailLibelleConverti

            ?.toLowerCase()

            .includes("partiel")

    ) {

        score += 8;

        trace.push("part_time");

    }

    // -----------------------------
    // Strategic sectors
    // -----------------------------

    const strategic = new Set([

        "81.21Z",

        "49.41A",

        "49.41B",

        "88.10A",

        "69.20Z"

    ]);

    if (strategic.has(p.codeNAF)) {

        score += 10;

        trace.push("strategic_sector");

    }

    // -----------------------------
    // Priority
    // -----------------------------

    let priority = "LOW";
    let stars = "★☆☆☆☆";
    let action = "Surveiller";

    if (score >= 90) {

        priority = "CRITICAL";
        stars = "★★★★★";
        action = "Appeler aujourd'hui";

    }

    else if (score >= 70) {

        priority = "HIGH";
        stars = "★★★★☆";
        action = "Contacter sous 48h";

    }

    else if (score >= 50) {

        priority = "MEDIUM";
        stars = "★★★☆☆";
        action = "Campagne email";

    }

    else if (score >= 30) {

        priority = "LOW";
        stars = "★★☆☆☆";
        action = "Nurturing";

    }

    return {

        json: {

            ...p,

            signal_score: score,

            priority,

            priority_stars: stars,

            recommended_action: action,

            qualification_trace: trace

        }

    };

});
